(5425429, 780548, 93565, '<td valign="top">Not voting because I''m in the challenge with you.<br/>I really like this. The tiny filaments projecting from the bud are great, and the way the larger "bristles" are all curling away from the center is very neat.</td>', 'Not voting because I''m in the challenge with you.I really like this. The tiny filaments projecting from the bud are great, and the way the larger "bristles" are all curling away from the center is very neat.', '2009-04-08 01:48:56.000000', NULL, 1),
(5425435, 780301, 80167, '<td valign="top">This is a great concept and well executed IMHO, except for the noise at the bottom of the image. Great work, otherwise! 7</td>', 'This is a great concept and well executed IMHO, except for the noise at the bottom of the image. Great work, otherwise! 7', '2009-04-08 01:49:35.000000', NULL, 1),
(5425450, 780491, 80167, '<td valign="top">The light is a little too harsh for my liking - the shadowed side seems quite dark. I do like the gray background, though.</td>', 'The light is a little too harsh for my liking - the shadowed side seems quite dark. I do like the gray background, though.', '2009-04-08 01:53:09.000000', NULL, 1),
