(5428269, 780516, 38162, '<td valign="top">welcome to the graveyard of abstracts - I love this. 8.5</td>', 'welcome to the graveyard of abstracts - I love this. 8.5', '2009-04-08 23:03:22.000000', NULL, 1),
(5428271, 780166, 103601, '<td valign="top">skin definitely has a nice texture</td>', 'skin definitely has a nice texture', '2009-04-08 23:03:55.000000', NULL, 1),
(5428275, 779784, 101256, '<td valign="top">The evenly top-to-bottom split DOF hurts this effort.  The concept is great and it just misses to really impact the viewer as it should. If it had, all the little fine details would have made it a certain top ten contender.</td>', 'The evenly top-to-bottom split DOF hurts this effort.  The concept is great and it just misses to really impact the viewer as it should. If it had, all the little fine details would have made it a certain top ten contender.', '2009-04-08 23:06:08.000000', NULL, 1),
(5428281, 780457, 101256, '<td valign="top">The sharp transition from soft focus to sharp focus is interesting in and of itself, but in this scene it doens''t work quite as well as it would in other scenes. It would have been better to concentrate on the bark molds and flora rather than the foreground which in this case, distracts from the really interesting blend of textures in the background.</td>', 'The sharp transition from soft focus to sharp focus is interesting in and of itself, but in this scene it doens''t work quite as well as it would in other scenes. It would have been better to concentrate on the bark molds and flora rather than the foreground which in this case, distracts from the really interesting blend of textures in the background.', '2009-04-08 23:08:15.000000', NULL, 1),
(5428285, 779072, 103601, '<td valign="top">interesting texture. i might have cropped it a little differently so it looked symmetric, but that''s just my taste. nice job</td>', 'interesting texture. i might have cropped it a little differently so it looked symmetric, but that''s just my taste. nice job', '2009-04-08 23:09:45.000000', NULL, 1),
(5428289, 780523, 103601, '<td valign="top">wow that is completely awesome</td>', 'wow that is completely awesome', '2009-04-08 23:14:26.000000', NULL, 1),
(5428290, 779999, 103601, '<td valign="top">excellent, powerful image</td>', 'excellent, powerful image', '2009-04-08 23:14:57.000000', NULL, 1),
(5428292, 780349, 101256, '<td valign="top">A nice effort demonstrating texture in the natural world. Interesting blend of color. It might have worked better a little closer concentrating on the log eliminating the grass in the foreground, but it works as it is. A good effort.</td>', 'A nice effort demonstrating texture in the natural world. Interesting blend of color. It might have worked better a little closer concentrating on the log eliminating the grass in the foreground, but it works as it is. A good effort.', '2009-04-08 23:15:51.000000', NULL, 1),
