(5428307, 780411, 103601, '<td valign="top">i think black and white works really well for this shot</td>', 'i think black and white works really well for this shot', '2009-04-08 23:24:05.000000', NULL, 1),
(5428310, 780470, 101256, '<td valign="top">An excellant capture with variable shapes, colors and textures which is very pleasing to the eye. The contrasting background compliments the rich purple and delicate nature of the petals.  A very good entry into the challenge - not perfect by any means, but purposeful and properly composed. Well done.</td>', 'An excellant capture with variable shapes, colors and textures which is very pleasing to the eye. The contrasting background compliments the rich purple and delicate nature of the petals.  A very good entry into the challenge - not perfect by any means, but purposeful and properly composed. Well done.', '2009-04-08 23:25:54.000000', NULL, 1),
(5428313, 780498, 101256, '<td valign="top">Simple and elegant with rich detail, excellant lighting. A sense of various textures is imparted with skill - a very good example of grayscale conversion. A top ten contender and a worthy entry into the challenge.</td>', 'Simple and elegant with rich detail, excellant lighting. A sense of various textures is imparted with skill - a very good example of grayscale conversion. A top ten contender and a worthy entry into the challenge.', '2009-04-08 23:27:23.000000', NULL, 1),
(5428314, 780143, 101256, '<td valign="top">This subject has been seen before and the different angle is very effective use of imagery in both instances. This should be a top ten image and if it didn''t win a ribbon, it would be highly unfortunate. Excellant tone control and inventive use of subtle color. Righ in detail, an excellant capture.</td>', 'This subject has been seen before and the different angle is very effective use of imagery in both instances. This should be a top ten image and if it didn''t win a ribbon, it would be highly unfortunate. Excellant tone control and inventive use of subtle color. Righ in detail, an excellant capture.', '2009-04-08 23:29:26.000000', NULL, 1),
(5428316, 780481, 80904, '<td valign="top">A tighter crop on this image would have made it stand out better.<br/> <br/>Like crop the top so the eye is in the thirds and crop from the righ to the nose and it would have filled the frame.</td>', 'A tighter crop on this image would have made it stand out better. Like crop the top so the eye is in the thirds and crop from the righ to the nose and it would have filled the frame.', '2009-04-08 23:29:56.000000', NULL, 1),
