(5428327, 780183, 103601, '<td valign="top">awesome composition</td>', 'awesome composition', '2009-04-08 23:38:10.000000', NULL, 1),
(5428329, 779645, 101256, '<td valign="top">A very good abstract demonstrating texture as per the challenge. Lots of detail with bits and pieces of variable texture. The blue appears to be a little over sharpened, but that is a positive as it imparts a sense of depth and dimension. A worthy challenge entry.</td>', 'A very good abstract demonstrating texture as per the challenge. Lots of detail with bits and pieces of variable texture. The blue appears to be a little over sharpened, but that is a positive as it imparts a sense of depth and dimension. A worthy challenge entry.', '2009-04-08 23:39:24.000000', NULL, 1),
(5428330, 779239, 101256, '<td valign="top">The soft focus isn''t the best choice to bring out the detail nature of this tree. A little sharper with less grain would enhance this in a positive way. A good solid effort to demonstrate texture.</td>', 'The soft focus isn''t the best choice to bring out the detail nature of this tree. A little sharper with less grain would enhance this in a positive way. A good solid effort to demonstrate texture.', '2009-04-08 23:41:20.000000', NULL, 1),
