(5429021, 779377, 103601, '<td valign="top">nice texture in the hand and the processing makes it a bit more interesting.</td>', 'nice texture in the hand and the processing makes it a bit more interesting.', '2009-04-09 11:18:07.000000', NULL, 1),
(5429022, 779522, 98339, '<td valign="top">very good focus...nice and sharp...good lighting too</td>', 'very good focus...nice and sharp...good lighting too', '2009-04-09 11:18:23.000000', NULL, 1),
(5429023, 780112, 103601, '<td valign="top">i like the background, it makes it seem like the pineapple is in its natural environment</td>', 'i like the background, it makes it seem like the pineapple is in its natural environment', '2009-04-09 11:18:34.000000', NULL, 1),
