(5429792, 780063, 66398, '<td valign="top">Not bad but not great.  dof either needs to be greater to bring the whole thing in focus or shallower and focus on an interesting portion of the photo. As it is now my eye wanders around trying to find a place to settle.</td>', 'Not bad but not great.  dof either needs to be greater to bring the whole thing in focus or shallower and focus on an interesting portion of the photo. As it is now my eye wanders around trying to find a place to settle.', '2009-04-09 19:43:07.000000', NULL, 1),
(5429793, 780052, 66398, '<td valign="top">Love the colors and composition.</td>', 'Love the colors and composition.', '2009-04-09 19:43:29.000000', NULL, 1),
