(5429796, 779074, 66398, '<td valign="top">I love old hands.</td>', 'I love old hands.', '2009-04-09 19:44:51.000000', NULL, 1),
(5429804, 779972, 66398, '<td valign="top">Looks like they''ve been well worn for sure. A little noisy in the sky but good composition.</td>', 'Looks like they''ve been well worn for sure. A little noisy in the sky but good composition.', '2009-04-09 19:46:07.000000', NULL, 1),
