(5430909, 780233, 101256, '<td valign="top">Elegant and simple with no major issues. A good solid entry into the challenge and worthy of a top 30 finish.</td>', 'Elegant and simple with no major issues. A good solid entry into the challenge and worthy of a top 30 finish.', '2009-04-10 16:52:35.000000', NULL, 1),
(5430910, 780168, 101256, '<td valign="top">Simpley elegant - a terrific example of natural world texture. Perfect lighting brings out the natural grains and unfinished beauty of the wood. A very worthy entry into the challenge and a solid contender for a ribbon.</td>', 'Simpley elegant - a terrific example of natural world texture. Perfect lighting brings out the natural grains and unfinished beauty of the wood. A very worthy entry into the challenge and a solid contender for a ribbon.', '2009-04-10 16:54:42.000000', NULL, 1),
(5430915, 779934, 101256, '<td valign="top">The white is just a tad overdone and the image has an appearance of being oversharpened. A good demonstration of texture and it''s use as a subject for this challenge. A good solid effort.</td>', 'The white is just a tad overdone and the image has an appearance of being oversharpened. A good demonstration of texture and it''s use as a subject for this challenge. A good solid effort.', '2009-04-10 16:56:34.000000', NULL, 1),
(5430918, 779953, 101256, '<td valign="top">An interesting conversin and a nice way demonstrate texture. Very intriguing subject matter. The variations of grain and structure are well presented. A good entry into the challenge.</td>', 'An interesting conversin and a nice way demonstrate texture. Very intriguing subject matter. The variations of grain and structure are well presented. A good entry into the challenge.', '2009-04-10 16:58:24.000000', NULL, 1),
(5430921, 780186, 101256, '<td valign="top">Another example of how controlled lighting only enhances the image - a very worthy effort without any major flaws. Nice and sharp, this should place relatively high in the challenge.  Well done.</td>', 'Another example of how controlled lighting only enhances the image - a very worthy effort without any major flaws. Nice and sharp, this should place relatively high in the challenge.  Well done.', '2009-04-10 17:00:25.000000', NULL, 1),
(5430923, 779999, 98647, '<td valign="top">I like the crop. Very dramatic.</td>', 'I like the crop. Very dramatic.', '2009-04-10 17:02:02.000000', NULL, 1),
(5430924, 780338, 101256, '<td valign="top">A good example of texture, but it appears a little less sharp than it should be and overall a little flatter than necessary. The DOF shift in the upper right corner is a distraction from the more interesting parts of the image. A good, solid effort demonstrataing texture.</td>', 'A good example of texture, but it appears a little less sharp than it should be and overall a little flatter than necessary. The DOF shift in the upper right corner is a distraction from the more interesting parts of the image. A good, solid effort demonstrataing texture.', '2009-04-10 17:02:46.000000', NULL, 1),
(5430927, 780277, 98647, '<td valign="top">I like the angle of the shot, and what it does to the shape of the building(?). Good textures all around too. Well done!</td>', 'I like the angle of the shot, and what it does to the shape of the building(?). Good textures all around too. Well done!', '2009-04-10 17:05:13.000000', NULL, 1),
(5430935, 780112, 98647, '<td valign="top">Nicely composed. Just wish the background was a bit less distracting.</td>', 'Nicely composed. Just wish the background was a bit less distracting.', '2009-04-10 17:08:46.000000', NULL, 1),
(5430936, 779591, 98647, '<td valign="top">The colours are what make this shot for me.</td>', 'The colours are what make this shot for me.', '2009-04-10 17:09:42.000000', NULL, 1),
