INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5431537, 780211, 73056, '<td valign="top">I like your composition!</td>', 'I like your composition!', '2009-04-11 01:39:22.000000', NULL, 1),
(5431539, 780334, 73056, '<td valign="top">Cool perspective.</td>', 'Cool perspective.', '2009-04-11 01:39:50.000000', NULL, 1),
(5431543, 780333, 73056, '<td valign="top">Nice shot. Just alittle flat in contrast.</td>', 'Nice shot. Just alittle flat in contrast.', '2009-04-11 01:46:33.000000', NULL, 1),
(5431544, 780480, 73056, '<td valign="top">I like the abstract feeling to this.</td>', 'I like the abstract feeling to this.', '2009-04-11 01:46:55.000000', NULL, 1),
(5431546, 779394, 73056, '<td valign="top">This shot makes me focus more on the perspective than textures. Nice eye though!</td>', 'This shot makes me focus more on the perspective than textures. Nice eye though!', '2009-04-11 01:48:15.000000', NULL, 1),
(5431554, 779848, 73056, '<td valign="top">I think you''re too far away for texture impact. Looks more like a landscape. Pretty spot though.</td>', 'I think you''re too far away for texture impact. Looks more like a landscape. Pretty spot though.', '2009-04-11 01:54:50.000000', NULL, 1),
(5431563, 780223, 73056, '<td valign="top">I like the varying lines in this.</td>', 'I like the varying lines in this.', '2009-04-11 01:59:23.000000', NULL, 1),
(5431580, 780531, 77521, '<td valign="top">ah! this is sooooo amazing! ten ten! GORGEOUS MACRO SHOT! GOOD LUCK!</td>', 'ah! this is sooooo amazing! ten ten! GORGEOUS MACRO SHOT! GOOD LUCK!', '2009-04-11 02:42:34.000000', NULL, 1),
(5431589, 779602, 66398, '<td valign="top">What''s on his head? Now I know. So they had to stamp him huh? Well character it is then. He''s awefully cute.</td>', 'What''s on his head? Now I know. So they had to stamp him huh? Well character it is then. He''s awefully cute.', '2009-04-11 03:08:02.000000', NULL, 1),
(5431590, 780165, 66398, '<td valign="top">90 degrees to the left would have been a better orientation imo since most people try to read the words when there are words in the shot. Having to rotate my head to read it. Maybe you did it to discourage reading the words and encourage viewing the texture but the mind works the way it works.</td>', '90 degrees to the left would have been a better orientation imo since most people try to read the words when there are words in the shot. Having to rotate my head to read it. Maybe you did it to discourage reading the words and encourage viewing the texture but the mind works the way it works.', '2009-04-11 03:09:14.000000', NULL, 1),
(5431607, 780183, 66398, '<td valign="top">This is a great shot for the challenge. After going through so many photos its nice when I get to the ones that have a good texture but also give me something else to look at that brings it into a realm of comprehension. The window tells me its an old building wall. Technical is great, meets the challenge well and it has interest. 7</td>', 'This is a great shot for the challenge. After going through so many photos its nice when I get to the ones that have a good texture but also give me something else to look at that brings it into a realm of comprehension. The window tells me its an old building wall. Technical is great, meets the challenge well and it has interest. 7', '2009-04-11 03:26:37.000000', NULL, 1),
(5431608, 779989, 66398, '<td valign="top">The color seems a little ''off'' to me. Diffused lighting might have alleviated the blown out portions.</td>', 'The color seems a little ''off'' to me. Diffused lighting might have alleviated the blown out portions.', '2009-04-11 03:28:27.000000', NULL, 1),
(5431609, 780531, 66398, '<td valign="top">If this isn''t Ursula then you have a style that''s similar to hers (which is a great complement!!</td>', 'If this isn''t Ursula then you have a style that''s similar to hers (which is a great complement!!', '2009-04-11 03:29:13.000000', NULL, 1),
(5431612, 780004, 66398, '<td valign="top">Some diffused side lighting might have made this better.</td>', 'Some diffused side lighting might have made this better.', '2009-04-11 03:30:37.000000', NULL, 1),
(5431616, 779573, 66398, '<td valign="top">The shadow on the bottom is distracting. This is a nice subject for texture but I think it would be more apparent if you moved or zoomed in closer.</td>', 'The shadow on the bottom is distracting. This is a nice subject for texture but I think it would be more apparent if you moved or zoomed in closer.', '2009-04-11 03:32:49.000000', NULL, 1),
(5431620, 780388, 66398, '<td valign="top">The white balance seems to be a little off. Harsh lighting like this doesn''t bring out their beauty as well as a diffused light might have.</td>', 'The white balance seems to be a little off. Harsh lighting like this doesn''t bring out their beauty as well as a diffused light might have.', '2009-04-11 03:35:00.000000', NULL, 1),
(5431623, 780523, 66398, '<td valign="top">That is crazy. I''ve never seen a pattern like that in someone''s eye. Now I think I might be invading some peoples personal space to get a good look at their eyes.</td>', 'That is crazy. I''ve never seen a pattern like that in someone''s eye. Now I think I might be invading some peoples personal space to get a good look at their eyes.', '2009-04-11 03:37:01.000000', NULL, 1),
(5431629, 779356, 66398, '<td valign="top">Oh so yummy baked with butter, brown sugar and cinnamon. Never tried it with butter and honey but I hear it''s pretty good.</td>', 'Oh so yummy baked with butter, brown sugar and cinnamon. Never tried it with butter and honey but I hear it''s pretty good.', '2009-04-11 03:44:23.000000', NULL, 1),
(5431635, 780450, 66398, '<td valign="top">My second favorite so far.Temporary rating of 5 for sorting purposes only. My Red ribbon choice after seeing all the shots in the challenge. Bumped to 9.</td>', 'My second favorite so far.Temporary rating of 5 for sorting purposes only. My Red ribbon choice after seeing all the shots in the challenge. Bumped to 9.', '2009-04-11 03:48:30.000000', NULL, 1),
(5431639, 779042, 66398, '<td valign="top">I like this shot. Something to think about though. If you moved yourself back and to the right a little to get more of a straight on shot and have the door in the bottom right of the photo and include the whole window in the shot it may have made a better image. Now of course I wasn''t there and I don''t know if there was some other issue as to why you couldn''t have done that but its something to think about anyway.</td>', 'I like this shot. Something to think about though. If you moved yourself back and to the right a little to get more of a straight on shot and have the door in the bottom right of the photo and include the whole window in the shot it may have made a better image. Now of course I wasn''t there and I don''t know if there was some other issue as to why you couldn''t have done that but its something to think about anyway.', '2009-04-11 03:53:54.000000', NULL, 1),
(5431642, 780516, 66398, '<td valign="top">This seems upside down to me. It''s also quite noisy.</td>', 'This seems upside down to me. It''s also quite noisy.', '2009-04-11 03:55:54.000000', NULL, 1),
(5431645, 780330, 66398, '<td valign="top">shallow dof works for this and the focus is in the right spot.</td>', 'shallow dof works for this and the focus is in the right spot.', '2009-04-11 03:56:52.000000', NULL, 1),
(5431646, 780120, 66398, '<td valign="top">I could see this as one of those motivational posters.</td>', 'I could see this as one of those motivational posters.', '2009-04-11 03:58:08.000000', NULL, 1),
(5431649, 779101, 101668, '<td valign="top">Wonderful picture. Love the light on the feathers</td>', 'Wonderful picture. Love the light on the feathers', '2009-04-11 03:59:22.000000', NULL, 1),
(5431651, 780301, 66398, '<td valign="top">It''s a little hot on the top of the photo and the bottom portion seems to have quite a bit of noise. It does meet the challenge but honestly it isn''t that interesting to look at.... well at least for me.</td>', 'It''s a little hot on the top of the photo and the bottom portion seems to have quite a bit of noise. It does meet the challenge but honestly it isn''t that interesting to look at.... well at least for me.', '2009-04-11 04:00:23.000000', NULL, 1),
(5431652, 778833, 66398, '<td valign="top">Please don''t put that in you drink though. Kind of looks a little radioactive. Nice texture shot.</td>', 'Please don''t put that in you drink though. Kind of looks a little radioactive. Nice texture shot.', '2009-04-11 04:01:53.000000', NULL, 1),
(5431654, 778977, 66398, '<td valign="top">Not really sure what the vegetable is but I''m not a fan of the processing here.</td>', 'Not really sure what the vegetable is but I''m not a fan of the processing here.', '2009-04-11 04:03:00.000000', NULL, 1),
(5431656, 780192, 66398, '<td valign="top">I like the reflection. Lighting is well done.</td>', 'I like the reflection. Lighting is well done.', '2009-04-11 04:03:25.000000', NULL, 1),
(5431661, 780422, 66398, '<td valign="top">What are those things. It almost looks like bone of some kind with brain attached.</td>', 'What are those things. It almost looks like bone of some kind with brain attached.', '2009-04-11 04:06:09.000000', NULL, 1),
(5431667, 780295, 66398, '<td valign="top">It''s such a pretty piece of wood isn''t it? Nice catch. Just wish the bottom right corner was in focus too. Greater dof would have made this a better photo. Still very nice though.</td>', 'It''s such a pretty piece of wood isn''t it? Nice catch. Just wish the bottom right corner was in focus too. Greater dof would have made this a better photo. Still very nice though.', '2009-04-11 04:13:02.000000', NULL, 1),
