(5436622, 780403, 66398, '<td valign="top">The shadow play helps add texture here. On the left it''s about shadow and light and on the right the contrast in color is good as well as the droplets of water.</td>', 'The shadow play helps add texture here. On the left it''s about shadow and light and on the right the contrast in color is good as well as the droplets of water.', '2009-04-14 13:10:20.000000', NULL, 1),
(5436624, 780223, 66398, '<td valign="top">Well done. I like the inclusion of the posts in the bottom of the photo.</td>', 'Well done. I like the inclusion of the posts in the bottom of the photo.', '2009-04-14 13:11:03.000000', NULL, 1),
